def calc(e):
    """The value of an expression as written, checked to be a whole number."""
    code = e
    for a, b in (("×", "*"), ("÷", "/"), ("−", "-"), ("[", "("), ("]", ")"), ("{", "("), ("}", ")")):
        code = code.replace(a, b)
    v = F(eval(code, {"__builtins__": {}})).limit_denominator(1000)  # noqa: S307  our own strings only
    assert v.denominator == 1, e
    return int(v)


